from collections import defaultdict
import json

# In-memory database for grocery items
grocery_db = defaultdict(lambda: {'name': '', 'quantity': 0})

def get_grocery(grocery_id):
    return grocery_db.get(grocery_id, {'error': 'Grocery not found'})

def list_groceries():
    return {grocery_id: grocery for grocery_id, grocery in grocery_db.items()}

def create_grocery(name, quantity):
    grocery_id = max(grocery_db.keys()) + 1 if grocery_db else 1
    grocery_db[grocery_id] = {'name': name, 'quantity': quantity}
    return grocery_db[grocery_id]

def update_grocery(grocery_id, name=None, quantity=None):
    if grocery_id not in grocery_db:
        return {'error': 'Grocery not found'}

    if name is not None:
        grocery_db[grocery_id]['name'] = name
    if quantity is not None:
        grocery_db[grocery_id]['quantity'] = quantity

    return grocery_db[grocery_id]

def delete_grocery(grocery_id):
    if grocery_id not in grocery_db:
        return {'error': 'Grocery not found'}

    del grocery_db[grocery_id]
    return {'id': grocery_id, 'success': True}

