from flask import Flask, jsonify, request

app = Flask(__name__)

# In-memory grocery database
groceries = []

def find_grocery(id):
    return next((g for g in groceries if g['id'] == id), None)

@app.route('/groceries', methods=['GET'])
def get_groceries():
    return jsonify(groceries)

@app.route('/groceries/<int:id>', methods=['GET'])
def get_grocery_by_id(id):
    grocery = find_grocery(id)
    if not grocery:
        return jsonify({'error': 'Grocery not found'}), 404
    return jsonify(grocery)

@app.route('/groceries', methods=['POST'])
def create_grocery():
    new_grocery = request.get_json()
    if not new_grocery or 'name' not in new_grocery or 'quantity' not in new_grocery:
        return jsonify({'error': 'Invalid request'}), 400
    new_grocery['id'] = len(groceries) + 1
    groceries.append(new_grocery)
    return jsonify(new_grocery), 201

@app.route('/groceries/<int:id>', methods=['PUT'])
def update_grocery(id):
    grocery = find_grocery(id)
    if not grocery:
        return jsonify({'error': 'Grocery not found'}), 404
    updated_grocery = request.get_json()
    if not updated_grocery or 'name' not in updated_grocery or 'quantity' not in updated_grocery:
        return jsonify({'error': 'Invalid request'}), 400
    grocery.update(updated_grocery)
    return jsonify(grocery)

@app.route('/groceries/<int:id>', methods=['DELETE'])
def delete_grocery(id):
    global groceries
    grocery = find_grocery(id)
    if not grocery:
        return jsonify({'error': 'Grocery not found'}), 404
    groceries = [g for g in groceries if g['id'] != id]
    return jsonify({'message': 'Grocery deleted'})

if __name__ == '__main__':
    app.run(debug=True)

