    return connection('groceries')
      .insert(grocery)
      .returning('*');
  }

  async update(id: number, grocery: Partial<Grocery>): Promise<Grocery| null> {
    return connection('groceries')
      .where({ id })
      .update(grocery)
      .returning('*');
  }

