package models

import (
    "database/sql"
)

var db *sql.DB

func ListAllGroceries() []Grocery {
    var grocer []Grocery
    rows, _ := db.Query("SELECT id, name, quantity FROM groceries")
    defer rows.Close()
    for rows.Next() {
        var g Grocery
        rows.Scan(&g.ID, &g.Name, &g.Quantity)
        grocer = append(grocer, g)
    }
    return grocer
}

func GetGroceryByID(id string) (Grocery, error) {
    var g Grocery
    err := db.QueryRow("SELECT id, name, quantity FROM groceries WHERE id=$1", id).Scan(&g.ID, &g.Name, &g.Quantity)
    return g, err
}

func CreateGrocery(g *Grocery) error {
    _, err := db.Exec("INSERT INTO groceries (name, quantity) VALUES ($1, $2)", g.Name, g.Quantity)
    return err
}

func UpdateGroceryByID(id string, g *Grocery) error {
    _, err := db.Exec("UPDATE groceries SET name=$1, quantity=$2 WHERE id=$3", g.Name, g.Quantity, id)
    return err
}

func DeleteGroceryByID(id string) error {
    _, err := db.Exec("DELETE FROM groceries WHERE id=$1", id)
    return err
}

