package com.example.demo.service;

import com.example.demo.model.Grocery;
import com.example.demo.repository.GroceryRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.Optional;

@Service
public class GroceryService {

    @Autowired
    private GroceryRepository groceryRepository;

    public List<Grocery> getAllGroceries() {
        return groceryRepository.findAll();
    }

    public Grocery getGroceryById(Long id) {
        Optional<Grocery> optionalGrocery = groceryRepository.findById(id);
        return optionalGrocery.orElse(null);
    }

    public Grocery createGrocery(Grocery grocery) {
        return groceryRepository.save(grocery);
    }

    public Grocery updateGrocery(Long id, Grocery groceryDetails) {
        Optional<Grocery> optionalGrocery = groceryRepository.findById(id);
        if (optionalGrocery.isPresent()) {
            Grocery updateGrocery = optionalGrocery.get();
            updateGrocery.setName(groceryDetails.getName());
            updateGrocery.setQuantity(groceryDetails.getQuantity());
            return groceryRepository.save(updateGrocery);
        }
        return null;
    }

    public boolean deleteGrocery(Long id) {
        if (groceryRepository.findById(id).isPresent()) {
            groceryRepository.deleteById(id);
            return true;
        }
        return false;
    }
}

