  res.json(groceries);
});

router.get('/:id', async (req, res) => {
  const { id } = req.params;
  const grocery = await getGroceryByIdUseCase(Number(id));
  if (grocery) {
    res.json(grocery);
  } else {
    res.status(404).json({ error: 'Grocery not found' });
  }
});

router.post('/', async (req, res) => {
  const { name, quantity } = req.body;
  if (!name || !quantity) {
    return res.status(400).json({ error: 'Name and quantity are required' });
  }
  const grocery = await createGroceryUseCase(name, quantity);
  res.status(201).json(grocery);
});

router.put('/:id', async (req, res) => {
  const { id } = req.params;
  const { name, quantity } = req.body;
  if (!name || !quantity) {
    return res.status(400).json({ error: 'Name and quantity are required' });
  }
  const grocery = await updateGroceryByIdUseCase(Number(id), name, quantity);
  if (grocery) {
    res.json(grocery);
  } else {
    res.status(404).json({ error: 'Grocery not found' });
  }
});

router.delete('/:id', async (req, res) => {
  const { id } = req.params;
  const result = await deleteGroceryByIdUseCase(Number(id));
  if (result) {
    res.sendStatus(204);
  } else {
    res.status(404).json({ error: 'Grocery not found' });
  }
});

export default router;

