use std::collections::HashMap;
use warp::{reply::Json, Filter};

#[derive(Debug)]
struct Grocery {
    name: String,
    quantity: u32,
}

#[derive(Debug)]
struct State(HashMap<i32, Grocery>);

impl State {
    fn new() -> Self {
        State(HashMap::new())
    }

    async fn list(&self) -> Json {
        serde_json::json!(self.0.values().cloned())
    }

    async fn get(&self, id: i32) -> Json {
        serde_json::json!(self.0.get(&id).cloned())
    }

    async fn create(&mut self, grocery: Grocery) -> Json {
        let id = self.0.len() as i32 + 1;
        self.0.insert(id, grocery);
        serde_json::json!(self.0.get(&id).cloned())
    }

    async fn update(&mut self, id: i32, grocery: Grocery) -> Json {
        if let Some(grocery) = self.0.get_mut(&id) {
            *grocery = grocery.clone();
        }
        serde_json::json!(self.0.get(&id).cloned())
    }

    async fn delete(&mut self, id: i32) -> Json {
        if let Some(_) = self.0.remove(&id) {
            serde_json::json!({})
        } else {
            serde_json::json!({ "error": "Resource not found" })
        }
    }
}

fn main() {
    let state = State::new();

    let list_route = warp::path("groceries")
        .and(warp::get())
        .map(move || state.list());

    let get_route = warp::path!("groceries" / i32)
        .and(warp::get())
        .map(move |id| state.get(id));

    let create_route = warp::path("groceries")
        .and(warp::post())
        .and(warp::json::<Grocery>())
        .map(move |grocery| state.create(grocery));

    let update_route = warp::path!("groceries" / i32)
        .and(warp::put())
        .and(warp::json::<Grocery>())
        .map(move |id, grocery| state.update(id, grocery));

    let delete_route = warp::path!("groceries" / i32)
        .and(warp::delete())
        .map(move |id| state.delete(id));

    let routes = list_route
        .or(get_route)
        .or(create_route)
        .or(update_route)
        .or(delete_route);

    warp::serve(routes).run(([127, 0, 0, 1], 3030));
}

