RSpec.describe GroceriesController, type: :controller do
  let(:valid_attributes) {
    { name: 'Milk', quantity: 2 }
  }

  let(:invalid_attributes) {
    { name: nil, quantity: nil }
  }

  describe "GET #index" do
    it "returns a success response" do
      get :index
      expect(response).to be_successful
    end

    it "returns all groceries" do
      grocery = Grocery.create(valid_attributes)
      get :index
      expect(assigns(:groceries)).to eq([grocery])
    end
  end

  describe "GET #show" do
    let!(:grocery) { Grocery.create(valid_attributes) }

    it "returns a success response" do
      get :show, params: { id: grocery.to_param }
      expect(response).to be_successful
    end

    it "returns the correct grocery" do
      get :show, params: { id: grocery.to_param }
      expect(assigns(:grocery)).to eq(grocery)
    end

    it "returns a 404 response when grocery is not found" do
      expect {
        get :show, params: { id: '999' }
      }.to raise_error(ActiveRecord::RecordNotFound)
    end
  end

  describe "POST #create" do
    context "with valid parameters" do
      it "creates a new Grocery" do
        expect {
          post :create, params: { grocery: valid_attributes }
        }.to change(Grocery, :count).by(1)
      end

      it "returns a success response" do
        post :create, params: { grocery: valid_attributes }
        expect(response).to have_http_status(:created)
      end
    end

    context "with invalid parameters" do
      it "does not create a new Grocery" do
        expect {
          post :create, params: { grocery: invalid_attributes }
        }.not_to change(Grocery, :count)
      end

      it "returns an unprocessable_entity response" do
        post :create, params: { grocery: invalid_attributes }
        expect(response).to have_http_status(:unprocessable_entity)
      end
    end
  end

  describe "PUT #update" do
    let!(:grocery) { Grocery.create(valid_attributes) }

    context "with valid parameters" do
      let(:new_attributes) {
        { name: 'Bread', quantity: 3 }
      }

      it "updates the requested grocery" do
        put :update, params: { id: grocery.to_param, grocery: new_attributes }
        grocery.reload
        expect(grocery.name).to eq('Bread')
        expect(grocery.quantity).to eq(3)
      end

      it "returns a success response" do
        put :update, params: { id: grocery.to_param, grocery: valid_attributes }
        expect(response).to have_http_status(:success)
      end
    end

    context "with invalid parameters" do
      it "returns an unprocessable_entity response" do
        put :update, params: { id: grocery.to_param, grocery: invalid_attributes }
        expect(response).to have_http_status(:unprocessable_entity)
      end
    end

    it "returns a 404 response when grocery is not found" do
