import java.util.Scanner;

public class Main {
    private static final Scanner scanner = new Scanner(System.in);
    private static final GroceryController controller = new GroceryController();

    public static void main(String[] args) {
        while (true) {
            System.out.println("1. Create grocery");
            System.out.println("2. Get all groceries");
            System.out.println("3. Get grocery by ID");
            System.out.println("4. Update grocery by ID");
            System.out.println("5. Delete grocery by ID");
            System.out.println("6. Exit");

            int choice = scanner.nextInt();
            scanner.nextLine(); // Consume newline

            switch (choice) {
                case 1:
                    createGrocery();
                    break;
                case 2:
                    getAllGroceries();
                    break;
                case 3:
                    getGroceryById();
                    break;
                case 4:
                    updateGrocery();
                    break;
                case 5:
                    deleteGrocery();
                    break;
                case 6:
                    return;
                default:
                    System.out.println("Invalid choice. Please try again.");
            }
        }
    }

    private static void createGrocery() {
        System.out.print("Enter grocery name: ");
        String name = scanner.nextLine();
        System.out.print("Enter quantity: ");
        int quantity = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        Grocery grocery = new Grocery(name, quantity);
        controller.createGrocery(grocery);

        System.out.println("Grocery created successfully.");
    }

    private static void getAllGroceries() {
        List<Grocery> groceries = controller.getAllGroceries();

        if (groceries.isEmpty()) {
            System.out.println("No groceries found.");
        } else {
            for (Grocery grocery : groceries) {
                System.out.println(grocery);
            }
        }
    }

    private static void getGroceryById() {
        System.out.print("Enter grocery ID: ");
        int id = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        Grocery grocery = controller.getGroceryById(id);

        if (grocery != null) {
            System.out.println(grocery);
        } else {
            System.out.println("Grocery not found.");
        }
    }

    private static void updateGrocery() {
        System.out.print("Enter grocery ID: ");
        int id = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        Grocery existingGrocery = controller.getGroceryById(id);

        if (existingGrocery == null) {
            System.out.println("Grocery not found.");
            return;
        }

        System.out.print("Enter new grocery name: ");
        String newName = scanner.nextLine();
        System.out.print("Enter new quantity: ");
        int newQuantity = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        Grocery updatedGrocery = new Grocery(id, newName, newQuantity);

        if (controller.updateGrocery(id, updatedGrocery)) {
            System.out.println("Grocery updated successfully.");
        } else {
            System.out.println("Failed to update grocery.");
        }
    }

    private static void deleteGrocery() {
        System.out.print("Enter grocery ID: ");
        int id = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        if (controller.deleteGrocery(id)) {
            System.out.println("Grocery deleted successfully.");
        } else {
            System.out.println("Failed to delete grocery.");
        }
    }
}

