package src.repositories;

import src.models.Grocery;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

public class GroceryRepository {
    private static List<Grocery> groceries = new ArrayList<>();
    private static int nextId = 1;

    // Create
    public Grocery create(Grocery grocery) {
        grocery.setId(nextId++);
        groceries.add(grocery);
        return grocery;
    }

    // Read All
    public List<Grocery> findAll() {
        return new ArrayList<>(groceries);
    }

    // Read by ID
    public Optional<Grocery> findById(int id) {
        return groceries.stream().filter(g -> g.getId() == id).findFirst();
    }

    // Update by ID
    public boolean update(int id, Grocery updatedGrocery) {
        for (int i = 0; i < groceries.size(); i++) {
            if (groceries.get(i).getId() == id) {
                groceries.set(i, updatedGrocery);
                return true;
            }
        }
        return false;
    }

    // Delete by ID
    public boolean delete(int id) {
        return groceries.removeIf(g -> g.getId() == id);
    }
}

