package app

type Grocery struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Quantity int    `json:"quantity"`
}

type Store interface {
	ListGroceries() []Grocery
	GetGroceryByID(id int) *Grocery
	CreateGrocery(name string, quantity int) *Grocery
	UpdateGroceryByID(id int, name string, quantity int) *Grocery
	DeleteGroceryByID(id int)
}

type InMemoryStore struct {
	groceries map[int]Grocery
	nextID    int
}

func NewInMemoryStore() *InMemoryStore {
	return &InMemoryStore{
		groceries: make(map[int]Grocery),
		nextID:    1,
	}
}

func (s *InMemoryStore) ListGroceries() []Grocery {
	var groceries []Grocery
	for _, grocery := range s.groceries {
		groceries = append(groceries, grocery)
	}
	return groceries
}

func (s *InMemoryStore) GetGroceryByID(id int) *Grocery {
	grocery, exists := s.groceries[id]
	if !exists {
		return nil
	}
	return &grocery
}

func (s *InMemoryStore) CreateGrocery(name string, quantity int) *Grocery {
	newGrocery := Grocery{
		ID:       s.nextID,
		Name:     name,
		Quantity: quantity,
	}
	s.groceries[s.nextID] = newGrocery
	s.nextID++
	return &newGrocery
}

func (s *InMemoryStore) UpdateGroceryByID(id int, name string, quantity int) *Grocery {
	grocery, exists := s.groceries[id]
	if !exists {
		return nil
	}
	grocery.Name = name
	grocery.Quantity = quantity
	s.groceries[id] = grocery
	return &grocery
}

func (s *InMemoryStore) DeleteGroceryByID(id int) {
	delete(s.groceries, id)
}

