package repository

import (
	"github.com/jmoiron/sqlx"
	"github.com/yourusername/groceryapi/models"
)

type GroceryRepository struct {
	db *sqlx.DB
}

func NewGroceryRepository(db *sqlx.DB) *GroceryRepository {
	return &GroceryRepository{db: db}
}

func (r *GroceryRepository) Create(grocery *models.Grocery) error {
	query := `INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, created_at, updated_at`
	return r.db.QueryRowx(query, grocery.Name, grocery.Quantity).StructScan(grocery)
}

func (r *GroceryRepository) GetByID(id int) (*models.Grocery, error) {
	grocery := &models.Grocery{}
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	err := r.db.Get(grocery, query, id)
	if err != nil {
		return nil, err
	}
	return grocery, nil
}

func (r *GroceryRepository) List() ([]*models.Grocery, error) {
	groceries := []*models.Grocery{}
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries`
	err := r.db.Select(&groceries, query)
	return groceries, err
}

func (r *GroceryRepository) UpdateByID(id int, grocery *models.Grocery) error {
	query := `UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING created_at, updated_at`
	return r.db.QueryRowx(query, grocery.Name, grocery.Quantity, id).StructScan(grocery)
}

func (r *GroceryRepository) DeleteByID(id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	_, err := r.db.Exec(query, id)
	return err
}

