package com.example.demo;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Optional;

@RestController
@RequestMapping("/groceries")
public class GroceryController {

    @Autowired
    private GroceryRepository groceryRepository;

    // Create a new grocery
    @PostMapping("/")
    public Grocery createGrocery(@RequestBody Grocery grocery) {
        return groceryRepository.save(grocery);
    }

    // Get all groceries
    @GetMapping("/")
    public List<Grocery> getAllGroceries() {
        return groceryRepository.findAll();
    }

    // Get a single grocery by id
    @GetMapping("/{id}")
    public ResponseEntity<Grocery> getGroceryById(@PathVariable Long id) {
        Optional<Grocery> grocery = groceryRepository.findById(id);
        if (grocery.isPresent()) {
            return ResponseEntity.ok(grocery.get());
        } else {
            return ResponseEntity.notFound().build();
        }
    }

    // Update a grocery by id
    @PutMapping("/{id}")
    public ResponseEntity<Grocery> updateGrocery(@PathVariable Long id, @RequestBody Grocery groceryDetails) {
        Optional<Grocery> optionalGrocery = groceryRepository.findById(id);
        if (optionalGrocery.isPresent()) {
            Grocery grocery = optionalGrocery.get();
            grocery.setName(groceryDetails.getName());
            grocery.setQuantity(groceryDetails.getQuantity());
            return ResponseEntity.ok(groceryRepository.save(grocery));
        } else {
            return ResponseEntity.notFound().build();
        }
    }

    // Delete a grocery by id
    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteGrocery(@PathVariable Long id) {
        if (groceryRepository.existsById(id)) {
            groceryRepository.deleteById(id);
            return ResponseEntity.noContent().build();
        } else {
            return ResponseEntity.notFound().build();
        }
    }
}

