package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"

	_ "github.com/go-sql-driver/mysql"
)

type Grocery struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Quantity int    `json:"quantity"`
}

func main() {
	db, err := sql.Open("mysql", "user:password@tcp(127.0.0.1:3306)/grocerydb")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	http.HandleFunc("/groceries", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			getGroceries(db, w, r)
		case http.MethodPost:
			createGrocery(db, w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	http.HandleFunc("/groceries/", func(w http.ResponseWriter, r *http.Request) {
		id := r.URL.Path[len("/groceries/"):]
		switch r.Method {
		case http.MethodGet:
			getGroceryByID(db, w, r, id)
		case http.MethodPut:
			updateGrocery(db, w, r, id)
		case http.MethodDelete:
			deleteGrocery(db, w, r, id)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	log.Println("Starting server on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

func getGroceries(db *sql.DB, w http.ResponseWriter, r *http.Request) {
	rows, err := db.Query("SELECT id, name, quantity FROM groceries")
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var groceries []Grocery
	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity); err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		groceries = append(groceries, g)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(groceries)
}

func getGroceryByID(db *sql.DB, w http.ResponseWriter, r *http.Request, id string) {
	var g Grocery
	if err := db.QueryRow("SELECT id, name, quantity FROM groceries WHERE id = ?", id).Scan(&g.ID, &g.Name, &g.Quantity); err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "Grocery not found", http.StatusNotFound)
		} else {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(g)
}

func createGrocery(db *sql.DB, w http.ResponseWriter, r *http.Request) {
	var g Grocery
	if err := json.NewDecoder(r.Body).Decode(&g); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	result, err := db.Exec("INSERT INTO groceries (name, quantity) VALUES (?, ?)", g.Name, g.Quantity)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	g.ID, _ = result.LastInsertId()
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(g)
}

func updateGrocery(db *sql.DB, w http.ResponseWriter, r *http.Request, id string) {
	var g Grocery
	if err := json.NewDecoder(r.Body).Decode(&g); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	result, err := db.Exec("UPDATE groceries SET name = ?, quantity = ? WHERE id = ?", g.Name, g.Quantity, id)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	rowsAffected, _ := result.RowsAffected()
	if rowsAffected == 0 {
		http.Error(w, "Grocery not found", http.StatusNotFound)
		return
	}

	g.ID = parseInt(id)
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(g)
}

func deleteGrocery(db *sql.DB, w http.ResponseWriter, r *http.Request, id string) {
	result, err := db.Exec("DELETE FROM groceries WHERE id = ?", id)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	rowsAffected, _ := result.RowsAffected()
	if rowsAffected == 0 {
		http.Error(w, "Grocery not found", http.StatusNotFound)
		return
	}

	w.WriteHeader(http.StatusNoContent)
}

