const express = require('express');
const router = express.Router();
const { Grocery } = require('../models/Grocery');

// List all groceries
router.get('/', async (req, res) => {
  try {
    const groceries = await Grocery.findAll();
    res.json(groceries);
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});

// Get a grocery by id
router.get('/:id', async (req, res) => {
  try {
    const grocery = await Grocery.findByPk(req.params.id);
    if (!grocery) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    res.json(grocery);
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});

// Create a new grocery
router.post('/', async (req, res) => {
  try {
    const { name, quantity } = req.body;
    const grocery = await Grocery.create({ name, quantity });
    res.status(201).json(grocery);
  } catch (error) {
    res.status(400).json({ error: 'Invalid data' });
  }
});

// Update a grocery by id
router.put('/:id', async (req, res) => {
  try {
    const { name, quantity } = req.body;
    const grocery = await Grocery.findByPk(req.params.id);
    if (!grocery) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    await grocery.update({ name, quantity });
    res.json(grocery);
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});

// Delete a grocery by id
router.delete('/:id', async (req, res) => {
  try {
    const grocery = await Grocery.findByPk(req.params.id);
    if (!grocery) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    await grocery.destroy();
    res.json({ message: 'Grocery deleted' });
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});

module.exports = router;

