package com.example.demo.controller;

import com.example.demo.model.Grocery;
import com.example.demo.repository.GroceryRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/groceries")
public class GroceryController {

    @Autowired
    private GroceryRepository groceryRepository;

    @GetMapping
    public List<Grocery> getAllGroceries() {
        return groceryRepository.findAll();
    }

    @GetMapping("/{id}")
    public ResponseEntity<Grocery> getGroceryById(@PathVariable Long id) {
        return groceryRepository.findById(id)
                .map(ResponseEntity::ok)
                .orElseGet(() -> ResponseEntity.notFound().build());
    }

    @PostMapping
    public Grocery createGrocery(@RequestBody Grocery grocery) {
        return groceryRepository.save(grocery);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Grocery> updateGroceryById(@PathVariable Long id, @RequestBody Grocery groceryDetails) {
        return groceryRepository.findById(id)
                .map(grocery -> {
                    grocery.setName(groceryDetails.getName());
                    grocery.setQuantity(groceryDetails.getQuantity());
                    return ResponseEntity.ok(groceryRepository.save(grocery));
                })
                .orElseGet(() -> ResponseEntity.notFound().build());
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteGroceryById(@PathVariable Long id) {
        if (groceryRepository.existsById(id)) {
            groceryRepository.deleteById(id);
            return ResponseEntity.noContent().build();
        }
        return ResponseEntity.notFound().build();
    }
}

