use serde::{Deserialize, Serialize};
use actix_web::{web, HttpResponse, HttpResponseBuilder};
use std::collections::HashMap;

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Grocery {
    pub id: i32,
    pub name: String,
    pub quantity: i32,
}

impl Grocery {
    pub fn new(name: String, quantity: i32) -> Self {
        Self {
            id: 0, // Will be assigned by the database
            name,
            quantity,
        }
    }
}

// In-memory storage for demonstration (in production, use a database)
static mut GROCERIES: Option<Vec<Grocery>> = None;
static mut NEXT_ID: i32 = 0;

pub fn init() {
    unsafe {
        if GROCERIES.is_none() {
            GROCERIES = Some(Vec::new());
        }
        NEXT_ID = 0;
    }
}

pub async fn list_groceries() -> HttpResponse {
    let groceries = unsafe { GROCERIES.as_ref().unwrap() };
    HttpResponse::Ok().json(groceries.clone())
}

pub async fn get_grocery_by_id(id: i32) -> HttpResponse {
    let groceries = unsafe { GROCERIES.as_ref().unwrap() };
    let grocery = groceries.iter().find(|g| g.id == id);
    match grocery {
        Some(grocery) => HttpResponse::Ok().json(grocery.clone()),
        None => HttpResponse::NotFound().json("Grocery not found"),
    }
}

pub async fn create_grocery(grocery: Grocery) -> HttpResponse {
    let mut groceries = unsafe { GROCERIES.as_mut().unwrap() };
    let new_grocery = Grocery {
        id: unsafe { NEXT_ID += 1; NEXT_ID },
        name: grocery.name.clone(),
        quantity: grocery.quantity,
    };
    groceries.push(new_grocery.clone());
    HttpResponse::Created().json(new_grocery)
}

pub async fn update_grocery_by_id(id: i32, grocery: Grocery) -> HttpResponse {
    let mut groceries = unsafe { GROCERIES.as_mut().unwrap() };
    if let Some(index) = groceries.iter().position(|g| g.id == id) {
        groceries[index] = grocery.clone();
        HttpResponse::Ok().json(grocery)
    } else {
        HttpResponse::NotFound().json("Grocery not found")
    }
}

pub async fn delete_grocery_by_id(id: i32) -> HttpResponse {
    let mut groceries = unsafe { GROCERIES.as_mut().unwrap() };
    let removed = groceries.iter().position(|g| g.id == id);
    match removed {
        Some(index) => {
            groceries.remove(index);
            HttpResponse::NoContent().finish()
        }
        None => HttpResponse::NotFound().json("Grocery not found"),
    }
}

// Routes
pub fn routes() -> Vec<web::Route> {
    vec![
        web::route("/").to(list_groceries),
        web::route("/{}").to(get_grocery_by_id),
        web::route("/").post(create_grocery),
        web::route("/{}").put(update_grocery_by_id),
        web::route("/{}").delete(delete_grocery_by_id),
    ]
}

