import { v4 as uuidv4 } from 'uuid';

// In-memory storage (in a real app, this would be a database)
let groceries = [];

// List all groceries
export const listGroceries = (req, res) => {
  res.json(groceries);
};

// Get grocery by id
export const getGroceryById = (req, res) => {
  const { id } = req.params;
  const grocery = groceries.find(g => g.id === parseInt(id));

  if (!grocery) {
    return res.status(404).json({ error: 'Grocery not found' });
  }

  res.json(grocery);
};

// Create a new grocery
export const createGrocery = (req, res) => {
  const { name, quantity } = req.body;

  if (!name || !quantity) {
    return res.status(400).json({ error: 'Name and quantity are required' });
  }

  const newGrocery = {
    id: groceries.length > 0 ? Math.max(...groceries.map(g => g.id)) + 1 : 1,
    name,
    quantity
  };

  groceries.push(newGrocery);
  res.status(201).json(newGrocery);
};

// Update grocery by id
export const updateGroceryById = (req, res) => {
  const { id } = req.params;
  const { name, quantity } = req.body;

  const groceryIndex = groceries.findIndex(g => g.id === parseInt(id));

  if (groceryIndex === -1) {
    return res.status(404).json({ error: 'Grocery not found' });
  }

  if (!name && !quantity) {
    return res.status(400).json({ error: 'At least one field (name or quantity) is required' });
  }

  groceries[groceryIndex] = {
    ...groceries[groceryIndex],
    name: name || groceries[groceryIndex].name,
    quantity: quantity || groceries[groceryIndex].quantity
  };

  res.json(groceries[groceryIndex]);
};

// Delete grocery by id
export const deleteGroceryById = (req, res) => {
  const { id } = req.params;
  const groceryIndex = groceries.findIndex(g => g.id === parseInt(id));

  if (groceryIndex === -1) {
    return res.status(404).json({ error: 'Grocery not found' });
  }

  groceries.splice(groceryIndex, 1);
  res.status(204).end();
};

