use serde::{Deserialize, Serialize};
use std::fmt;

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct Grocery {
    pub id: i32,
    pub name: String,
    pub quantity: i32,
}

impl fmt::Display for Grocery {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Grocery(id={}, name='{}', quantity={})", self.id, self.name, self.quantity)
    }
}

#[derive(Debug)]
pub struct GroceryError {
    pub message: String,
}

impl GroceryError {
    pub fn new(message: &str) -> Self {
        Self {
            message: message.to_string(),
        }
    }
}

impl std::fmt::Display for GroceryError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Grocery error: {}", self.message)
    }
}

impl std::error::Error for GroceryError {}

