import { Grocery } from '../types/grocery';

export class GroceryService {
  private groceries: Grocery[] = [];

  async list(): Promise<Grocery[]> {
    return this.groceries;
  }

  async get(id: number): Promise<Grocery | null> {
    return this.groceries.find(grocery => grocery.id === id) || null;
  }

  async create(grocery: Omit<Grocery, 'id'>): Promise<Grocery> {
    const newGrocery: Grocery = {
      id: this.groceries.length > 0 ? Math.max(...this.groceries.map(g => g.id)) + 1 : 1,
      name: grocery.name,
      quantity: grocery.quantity,
    };
    this.groceries.push(newGrocery);
    return newGrocery;
  }

  async update(id: number, updatedData: Partial<Grocery>): Promise<Grocery | null> {
    const index = this.groceries.findIndex(grocery => grocery.id === id);
    if (index === -1) return null;

    this.groceries[index] = {
      ...this.groceries[index],
      ...updatedData,
    };

    return this.groceries[index];
  }

  async delete(id: number): Promise<boolean> {
    const index = this.groceries.findIndex(grocery => grocery.id === id);
    if (index === -1) return false;

