import Grocery from '../models/grocery.model.js';

// List all groceries
export const list = async (req, res) => {
  try {
    const groceries = await Grocery.find();
    res.json(groceries);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch groceries' });
  }
};

// Get a grocery by ID
export const get = async (req, res) => {
  try {
    const { id } = req.params;
    const grocery = await Grocery.findById(id);
    if (!grocery) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    res.json(grocery);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch grocery' });
  }
};

// Create a new grocery
export const create = async (req, res) => {
  try {
    const { name, quantity } = req.body;
    if (!name || !quantity) {
      return res.status(400).json({ error: 'Name and quantity are required' });
    }
    const grocery = new Grocery({ name, quantity });
    await grocery.save();
    res.status(201).json(grocery);
  } catch (error) {
    res.status(500).json({ error: 'Failed to create grocery' });
  }
};

// Update a grocery by ID
export const update = async (req, res) => {
  try {
    const { id } = req.params;
    const { name, quantity } = req.body;
    if (!name || !quantity) {
      return res.status(400).json({ error: 'Name and quantity are required' });
    }
    const grocery = await Grocery.findByIdAndUpdate(
      id,
      { name, quantity },
      { new: true }
    );
    if (!grocery) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    res.json(grocery);
  } catch (error) {
    res.status(500).json({ error: 'Failed to update grocery' });
  }
};

// Delete a grocery by ID
export const deleteById = async (req, res) => {
  try {
    const { id } = req.params;
    const grocery = await Grocery.findByIdAndDelete(id);
    if (!grocery) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    res.json({ message: 'Grocery deleted successfully' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to delete grocery' });
  }
};

