use actix_web::{web, HttpResponse, HttpServer, get, post, put, delete, Scope};
use serde::{Deserialize, Serialize};
use std::sync::Mutex;
use std::collections::HashMap;

// Define the Grocery model
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Grocery {
    pub id: i32,
    pub name: String,
    pub quantity: i32,
}

// In-memory storage (in a real app, you'd use a database)
static mut GROCERIES: Option<Vec<Grocery>> = None;
static mut GROCERY_MAP: Option<HashMap<i32, Grocery>> = None;

// Initialize the data (for demo)
fn init_groceries() {
    let mut groceries = vec![
        Grocery {
            id: 1,
            name: "Milk".to_string(),
            quantity: 2,
        },
        Grocery {
            id: 2,
            name: "Bread".to_string(),
            quantity: 1,
        },
        Grocery {
            id: 3,
            name: "Eggs".to_string(),
            quantity: 12,
        },
    ];

    let mut grocery_map = HashMap::new();
    for grocery in &groceries {
        grocery_map.insert(grocery.id, grocery.clone());
    }

    unsafe {
        GROCERIES = Some(groceries);
        GROCERY_MAP = Some(grocery_map);
    }
}

// Routes
pub fn setup_routes() -> Scope {
    let mut app = Scope::new("/groceries");

    // GET /groceries - list all groceries
    app.route("", get().async fn(list_groceries));

    // GET /groceries/{id} - get grocery by id
    app.route("/{id}", get().async fn(get_grocery_by_id));

    // POST /groceries - create new grocery
    app.route("", post().async fn(create_grocery));

    // PUT /groceries/{id} - update grocery by id
    app.route("/{id}", put().async fn(update_grocery_by_id));

    // DELETE /groceries/{id} - delete grocery by id
    app.route("/{id}", delete().async fn(delete_grocery_by_id));

    app
}

// List all groceries
async fn list_groceries() -> HttpResponse {
    let groceries = unsafe { GROCERIES.as_ref().unwrap().clone() };
    HttpResponse::Ok().json(groceries)
}

// Get grocery by id
async fn get_grocery_by_id(id: web::Path<i32>) -> HttpResponse {
    let id = id.into();
    let grocery = unsafe {
        GROCERY_MAP
            .as_ref()
            .unwrap()
            .get(&id)
            .cloned()
            .unwrap_or_else(|| {
                // If not found, return 404
                return HttpResponse::NotFound().json("Grocery not found");
            })
    };

    match grocery {
        Some(grocery) => HttpResponse::Ok().json(grocery),
        None => HttpResponse::NotFound().json("Grocery not found"),
    }
}

// Create a new grocery
async fn create_grocery(grocery: web::Json<Grocery>) -> HttpResponse {
    let mut groceries = unsafe { GROCERIES.as_mut().unwrap() };
    let mut grocery_map = unsafe { GROCERY_MAP.as_mut().unwrap() };

    // Find the next available ID
    let next_id = groceries
        .iter()
        .map(|g| g.id)
        .max()
        .unwrap_or(0)
        + 1;

    let new_grocery = Grocery {
        id: next_id,
        name: grocery.name.clone(),
        quantity: grocery.quantity,
    };

    groceries.push(new_grocery.clone());
    grocery_map.insert(next_id, new_grocery.clone());

    HttpResponse::Created().json(new_grocery)
}

// Update grocery by id
async fn update_grocery_by_id(id: web::Path<i32>, grocery: web::Json<Grocery>) -> HttpResponse {
    let id = id.into();
    let mut groceries = unsafe { GROCERIES.as_mut().unwrap() };
    let mut grocery_map = unsafe { GROCERY_MAP.as_mut().unwrap() };

    // Find the grocery by id
    let grocery_index = groceries
        .iter()
        .position(|g| g.id == id)
        .unwrap_or_else(|| return HttpResponse::NotFound().json("Grocery not found"));

    let old_grocery = groceries.remove(grocery_index);
    let updated_grocery = Grocery {
        id,
        name: grocery.name.clone(),
        quantity: grocery.quantity,
    };

    groceries.insert(grocery_index, updated_grocery.clone());
    grocery_map.insert(id, updated_grocery.clone());

    HttpResponse::Ok().json(updated_grocery)
}

// Delete grocery by id
async fn delete_grocery_by_id(id: web::Path<i32>) -> HttpResponse {
    let id = id.into();
    let mut groceries = unsafe { GROCERIES.as_mut().unwrap() };
    let mut grocery_map = unsafe { GROCERY_MAP.as_mut().unwrap() };

    // Find the grocery by id
    let index = groceries
        .iter()
        .position(|g| g.id == id)
        .unwrap_or_else(|| return HttpResponse::NotFound().json("Grocery not found"));

    let deleted_grocery = groceries.remove(index);
    grocery_map.remove(&id);

    HttpResponse::NoContent().finish()
}

// Initialize groceries on startup
pub fn start_server() {
    init_groceries();
}

