const Grocery = require('../models/Grocery');

// GET /groceries - List all groceries
exports.list = async (req, res) => {
  try {
    const groceries = await Grocery.findAll();
    res.json(groceries);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch groceries' });
  }
};

// GET /groceries/:id - Get grocery by ID
exports.get = async (req, res) => {
  try {
    const { id } = req.params;
    const grocery = await Grocery.findByPk(id);
    if (!grocery) {
      return res.status(404).json({ error: 'Grocery not found' });
    }
    res.json(grocery);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch grocery' });
  }
};

// POST /groceries - Create a new grocery
exports.create = async (req, res) => {
  try {
    const { name, quantity } = req.body;

    if (!name || !quantity) {
      return res.status(400).json({ error: 'Name and quantity are required' });
    }

    const grocery = await Grocery.create({ name, quantity });
    res.status(201).json(grocery);
  } catch (error) {
    res.status(500).json({ error: 'Failed to create grocery' });
  }
};

// PUT /groceries/:id - Update grocery by ID
exports.update = async (req, res) => {
  try {
    const { id } = req.params;
    const { name, quantity } = req.body;

    if (!name || !quantity) {
      return res.status(400).json({ error: 'Name and quantity are required' });
    }

    const grocery = await Grocery.findByPk(id);
    if (!grocery) {
      return res.status(404).json({ error: 'Grocery not found' });
    }

    await grocery.update({ name, quantity });
    res.json(grocery);
  } catch (error) {
    res.status(500).json({ error: 'Failed to update grocery' });
  }
};

// DELETE /groceries/:id - Delete grocery by ID
exports.delete = async (req, res) => {
  try {
    const { id } = req.params;
    const grocery = await Grocery.findByPk(id);
    if (!grocery) {
      return res.status(404).json({ error: 'Grocery not found' });
    }

    await grocery.destroy();
    res.status(204).send(); // No content on success
  } catch (error) {
    res.status(500).json({ error: 'Failed to delete grocery' });
  }
};

