  { id: 1, name: 'Milk', quantity: 2 },
  { id: 2, name: 'Bread', quantity: 1 }
];

let nextId = 3;

function findById(id) {
  return groceries.find(g => g.id === id);
}

function findAll() {
  return [...groceries];
}

function create(name, quantity) {
  const grocery = { id: nextId++, name, quantity };
  groceries.push(grocery);
  return grocery;
}

function update(id, name, quantity) {
  const index = groceries.findIndex(g => g.id === id);
  if (index === -1) return null;
  groceries[index] = { ...groceries[index], name, quantity };
  return groceries[index];
}

function delete(id) {
  const index = groceries.findIndex(g => g.id === id);
  if (index === -1) return false;
  groceries.splice(index, 1);
  return true;
}

module.exports = { findById, findAll, create, update, delete };

