  }

  static findAll() {
    return groceries;
  }

  static create(data) {
    const id = groceries.length + 1;
    const grocery = new Grocery({ ...data, id });
    groceries.push(grocery);
    return grocery;
  }

  static update(id, data) {
    const index = groceries.findIndex(grocery => grocery.id === id);
    if (index === -1) return null;
    groceries[index] = { ...groceries[index], ...data, id };
    return groceries[index];
  }

  static delete(id) {
    const index = groceries.findIndex(grocery => grocery.id === id);
    if (index === -1) return false;
    groceries.splice(index, 1);
    return true;
  }
}

