// main.go
package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
)

type Grocery struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Quantity int    `json:"quantity"`
}

var groceries = []Grocery{
	{ID: 1, Name: "Apples", Quantity: 5},
	{ID: 2, Name: "Bananas", Quantity: 3},
}

var nextID = 3

func main() {
	http.HandleFunc("/groceries", groceriesHandler)
	http.HandleFunc("/groceries/", groceryHandler)

	fmt.Println("Server starting on :8080")
	http.ListenAndServe(":8080", nil)
}

func groceriesHandler(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "GET":
		getGroceries(w, r)
	case "POST":
		createGrocery(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func groceryHandler(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Path[len("/groceries/"):]
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	switch r.Method {
	case "GET":
		getGrocery(w, r, id)
	case "PUT":
		updateGrocery(w, r, id)
	case "DELETE":
		deleteGrocery(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func getGroceries(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(groceries)
}

func createGrocery(w http.ResponseWriter, r *http.Request) {
	var newGrocery Grocery
	if err := json.NewDecoder(r.Body).Decode(&newGrocery); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	newGrocery.ID = nextID
	nextID++
	groceries = append(groceries, newGrocery)

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(newGrocery)
}

func getGrocery(w http.ResponseWriter, r *http.Request, id int) {
	for _, grocery := range groceries {
		if grocery.ID == id {
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(grocery)
			return
		}
	}
	http.Error(w, "Grocery not found", http.StatusNotFound)
}

func updateGrocery(w http.ResponseWriter, r *http.Request, id int) {
	var updatedGrocery Grocery
	if err := json.NewDecoder(r.Body).Decode(&updatedGrocery); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	for i, grocery := range groceries {
		if grocery.ID == id {
			updatedGrocery.ID = id
			groceries[i] = updatedGrocery

			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(updatedGrocery)
			return
		}
	}
	http.Error(w, "Grocery not found", http.StatusNotFound)
}

func deleteGrocery(w http.ResponseWriter, r *http.Request, id int) {
	for i, grocery := range groceries {
		if grocery.ID == id {
			groceries = append(groceries[:i], groceries[i+1:]...)
			w.WriteHeader(http.StatusNoContent)
			return
		}
	}
	http.Error(w, "Grocery not found", http.StatusNotFound)
}

