package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
)

type Grocery struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Quantity int    `json:"quantity"`
}

var (
	groceries = map[int]Grocery{
		1: {ID: 1, Name: "Apples", Quantity: 5},
		2: {ID: 2, Name: "Bananas", Quantity: 3},
	}
	nextID = 3
	mu     sync.RWMutex
)

func main() {
	http.HandleFunc("/groceries", groceriesHandler)
	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func groceriesHandler(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "GET":
		getGroceries(w, r)
	case "POST":
		createGrocery(w, r)
	case "PUT":
		updateGrocery(w, r)
	case "DELETE":
		deleteGrocery(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func getGroceries(w http.ResponseWriter, r *http.Request) {
	mu.RLock()
	defer mu.RUnlock()

	var list []Grocery
	for _, g := range groceries {
		list = append(list, g)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(list)
}

func getGroceryByID(w http.ResponseWriter, id int) {
	mu.RLock()
	defer mu.RUnlock()

	grocery, exists := groceries[id]
	if !exists {
		http.Error(w, "Grocery not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(grocery)
}

func createGrocery(w http.ResponseWriter, r *http.Request) {
	var grocery Grocery
	if err := json.NewDecoder(r.Body).Decode(&grocery); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	mu.Lock()
	grocery.ID = nextID
	groceries[nextID] = grocery
	nextID++
	mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(grocery)
}

func updateGrocery(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Path[strings.LastIndex(r.URL.Path, "/")+1:])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var updatedGrocery Grocery
	if err := json.NewDecoder(r.Body).Decode(&updatedGrocery); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	mu.Lock()
	grocery, exists := groceries[id]
	if !exists {
		http.Error(w, "Grocery not found", http.StatusNotFound)
		mu.Unlock()
		return
	}
	grocery.Name = updatedGrocery.Name
	grocery.Quantity = updatedGrocery.Quantity
	groceries[id] = grocery
	mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(grocery)
}

func deleteGrocery(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Path[strings.LastIndex(r.URL.Path, "/")+1:])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	mu.Lock()
	_, exists := groceries[id]
	if !exists {
		http.Error(w, "Grocery not found", http.StatusNotFound)
		mu.Unlock()
		return
	}
	delete(groceries, id)
	mu.Unlock()

	w.WriteHeader(http.StatusNoContent)
}

