package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
)

type Grocery struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Quantity int    `json:"quantity"`
}

var groceries []Grocery
var nextID int = 1

func main() {
	http.HandleFunc("/groceries", handleGroceries)
	http.HandleFunc("/groceries/", handleGrocery)

	fmt.Println("Server starting on :8080")
	http.ListenAndServe(":8080", nil)
}

func handleGroceries(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "GET":
		handleGetGroceries(w, r)
	case "POST":
		handleCreateGrocery(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func handleGrocery(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Path[len("/groceries/"):]
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	switch r.Method {
	case "GET":
		handleGetGrocery(w, r, id)
	case "PUT":
		handleUpdateGrocery(w, r, id)
	case "DELETE":
		handleDeleteGrocery(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func handleGetGroceries(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(groceries)
}

func handleCreateGrocery(w http.ResponseWriter, r *http.Request) {
	var grocery Grocery
	if err := json.NewDecoder(r.Body).Decode(&grocery); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	grocery.ID = nextID
	nextID++
	groceries = append(groceries, grocery)

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(grocery)
}

func handleGetGrocery(w http.ResponseWriter, r *http.Request, id int) {
	for _, grocery := range groceries {
		if grocery.ID == id {
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(grocery)
			return
		}
	}
	http.Error(w, "Grocery not found", http.StatusNotFound)
}

func handleUpdateGrocery(w http.ResponseWriter, r *http.Request, id int) {
	var updatedGrocery Grocery
	if err := json.NewDecoder(r.Body).Decode(&updatedGrocery); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	for i, grocery := range groceries {
		if grocery.ID == id {
			updatedGrocery.ID = id
			groceries[i] = updatedGrocery

			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(updatedGrocery)
			return
		}
	}
	http.Error(w, "Grocery not found", http.StatusNotFound)
}

func handleDeleteGrocery(w http.ResponseWriter, r *http.Request, id int) {
	for i, grocery := range groceries {
		if grocery.ID == id {
			groceries = append(groceries[:i], groceries[i+1:]...)
			w.WriteHeader(http.StatusNoContent)
			return
		}
	}
	http.Error(w, "Grocery not found", http.StatusNotFound)
}

