package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"sync"
)

type Grocery struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Quantity int    `json:"quantity"`
}

var (
	groceries = map[int]Grocery{
		1: {ID: 1, Name: "Apples", Quantity: 5},
		2: {ID: 2, Name: "Bananas", Quantity: 3},
	}
	nextID = 3
	mu     sync.RWMutex
)

func main() {
	http.HandleFunc("/groceries", groceriesHandler)
	http.HandleFunc("/groceries/", groceryHandler)

	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func groceriesHandler(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "GET":
		getGroceries(w, r)
	case "POST":
		createGrocery(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func groceryHandler(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Path[len("/groceries/"):]
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid grocery ID", http.StatusBadRequest)
		return
	}

	switch r.Method {
	case "GET":
		getGrocery(w, r, id)
	case "PUT":
		updateGrocery(w, r, id)
	case "DELETE":
		deleteGrocery(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func getGroceries(w http.ResponseWriter, r *http.Request) {
	mu.RLock()
	defer mu.RUnlock()

	var list []Grocery
	for _, grocery := range groceries {
		list = append(list, grocery)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(list)
}

func createGrocery(w http.ResponseWriter, r *http.Request) {
	var grocery Grocery
	if err := json.NewDecoder(r.Body).Decode(&grocery); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	mu.Lock()
	defer mu.Unlock()

	grocery.ID = nextID
	nextID++
	groceries[grocery.ID] = grocery

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(grocery)
}

func getGrocery(w http.ResponseWriter, r *http.Request, id int) {
	mu.RLock()
	defer mu.RUnlock()

	grocery, exists := groceries[id]
	if !exists {
		http.Error(w, "Grocery not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(grocery)
}

func updateGrocery(w http.ResponseWriter, r *http.Request, id int) {
	mu.RLock()
	grocery, exists := groceries[id]
	mu.RUnlock()

	if !exists {
		http.Error(w, "Grocery not found", http.StatusNotFound)
		return
	}

	var updates Grocery
	if err := json.NewDecoder(r.Body).Decode(&updates); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	mu.Lock()
	defer mu.Unlock()

	if updates.Name != "" {
		grocery.Name = updates.Name
	}
	if updates.Quantity != 0 {
		grocery.Quantity = updates.Quantity
	}

	groceries[id] = grocery

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(grocery)
}

func deleteGrocery(w http.ResponseWriter, r *http.Request, id int) {
	mu.Lock()
	defer mu.Unlock()

	_, exists := groceries[id]
	if !exists {
		http.Error(w, "Grocery not found", http.StatusNotFound)
		return
	}

	delete(groceries, id)

	w.WriteHeader(http.StatusNoContent)
}

